package unverified;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static unverified.ClonePairGenericInvocationTestSupport.*;

@Tag("timeout")
class ClonePair12409DifferenceFindingTest {

    private final ClonePair12409 subject = new ClonePair12409();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: no_termination.
     * Difference manifestation: the methods differ in whether they terminate.
     */
    @Test
    @BehavioralDifference(DifferenceType.NO_TERMINATION)
    void methodsDisagreeOnTermination() {
        InvocationOutcome method1Outcome = captureWithTimeout(values -> subject.method1((String) values[0], (String) values[1], (String) values[2]), 200L, "", "", "a");
        InvocationOutcome method2Outcome = captureWithTimeout(values -> subject.method2((String) values[0], (String) values[1], (String) values[2]), 200L, "", "", "a");

        assertEquals("OK", method1Outcome.status);
        assertEquals("TIMEOUT", method2Outcome.status);
    }
}
